package com.almaraama.shared.id;

import java.util.Objects;
import java.util.UUID;

/** Public identifier of a unit (lot) (sites module), referenced by other modules (CF-2, CF-10). */
public record UnitId(UUID value) {

    public UnitId {
        Objects.requireNonNull(value, "value");
    }

    /** A new UUID v7 identifier, generated by the application (CF-10). */
    public static UnitId newId() {
        return new UnitId(UuidV7.next());
    }

    /** The UUID in its canonical text form. */
    @Override
    public String toString() {
        return value.toString();
    }
}
